-- Additive recovery: original scenes, paid claims and DO task results remain permanent.
CREATE TABLE tower_scene_repairs(
 id TEXT PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 48), mode TEXT NOT NULL CHECK(mode IN('resume','replace')),
 source_id TEXT NOT NULL REFERENCES tower_scenes(id), target_id TEXT NOT NULL, logical_slot TEXT NOT NULL,
 scene_key TEXT NOT NULL, root_batch TEXT, repair_batch TEXT, attempt INTEGER NOT NULL CHECK(attempt BETWEEN 0 AND 2),
 baseline_sha TEXT NOT NULL, bible_version TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK((mode='resume' AND target_id=source_id AND repair_batch IS NULL) OR (mode='replace' AND target_id!=source_id AND repair_batch IS NOT NULL))
);
CREATE UNIQUE INDEX tower_scene_replacement_target ON tower_scene_repairs(target_id) WHERE mode='replace';
CREATE UNIQUE INDEX tower_scene_replacement_source ON tower_scene_repairs(source_id) WHERE mode='replace';
CREATE TABLE tower_scene_repair_events(repair_id TEXT NOT NULL REFERENCES tower_scene_repairs(id),event TEXT NOT NULL CHECK(event IN('started','settled')),scene_state TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(repair_id,event));
CREATE VIEW tower_scene_canonical AS SELECT s.*,COALESCE(r.logical_slot,s.id) logical_slot,COALESCE(r.root_batch,s.batch_id) root_batch,COALESCE(r.attempt,0) attempt FROM tower_scenes s LEFT JOIN tower_scene_repairs r ON r.mode='replace' AND r.target_id=s.id WHERE NOT EXISTS(SELECT 1 FROM tower_scene_repairs newer WHERE newer.mode='replace' AND newer.source_id=s.id AND EXISTS(SELECT 1 FROM tower_scenes target WHERE target.id=newer.target_id));
CREATE TRIGGER tower_scene_repair_scope BEFORE INSERT ON tower_scene_repairs WHEN
 EXISTS(SELECT 1 FROM tower_scene_repairs WHERE id=NEW.id) OR
 NOT EXISTS(SELECT 1 FROM tower_scene_canonical s WHERE s.id=NEW.source_id AND s.id NOT IN('seed-v1-01','seed-v1-02','seed-v1-05') AND s.logical_slot NOT IN('seed-v1-01','seed-v1-02','seed-v1-05') AND NEW.logical_slot=s.logical_slot AND NEW.scene_key=s.scene_key AND NEW.root_batch IS s.root_batch AND NEW.baseline_sha=s.baseline_sha AND NEW.bible_version=s.bible_version
 AND NOT EXISTS(SELECT 1 FROM tower_scene_calls c JOIN manager_jobs j ON j.id=c.job_id WHERE c.scene_id=s.id AND (j.state!='complete' OR j.actual_micro IS NULL OR j.actual_micro>j.reserved_micro))
 AND abs(julianday(NEW.created_at)-julianday('now'))<1.0/1440
 AND ((NEW.mode='resume' AND s.state='blocked' AND (s.error_code='token_count_unavailable' OR s.error_code LIKE 'token_count_http_%' OR s.error_code IN('token_count_timeout','token_count_network','token_count_invalid')) AND NEW.attempt=s.attempt AND (SELECT count(*) FROM tower_scene_repairs WHERE source_id=s.id AND mode='resume')<3 AND NOT EXISTS(SELECT 1 FROM tower_scene_repairs r WHERE r.source_id=s.id AND r.mode='resume' AND NOT EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='settled')) AND NOT EXISTS(SELECT 1 FROM tower_scene_calls c WHERE c.scene_id=s.id AND c.purpose='review') AND (SELECT count(*) FROM tower_scene_calls WHERE scene_id=s.id) IN(0,2) AND ((s.plan_json IS NULL AND s.object_key IS NULL) OR (s.plan_json IS NOT NULL AND s.object_key IS NOT NULL)))
 OR (NEW.mode='replace' AND s.batch_id IS NOT NULL AND s.state='invalid' AND s.error_code='scene_review_failed' AND NEW.attempt=s.attempt+1 AND NEW.attempt<=2 AND NEW.target_id=s.logical_slot||'-r'||NEW.attempt AND NEW.repair_batch='repair-'||NEW.id AND NEW.repair_batch!=s.batch_id AND NOT EXISTS(SELECT 1 FROM tower_scenes WHERE id=NEW.target_id) AND (SELECT count(*) FROM tower_scene_calls c JOIN manager_jobs j ON j.id=c.job_id WHERE c.scene_id=s.id AND j.state='complete' AND j.actual_micro IS NOT NULL)=3 AND EXISTS(SELECT 1 FROM tower_scene_calls c JOIN tower_scene_results r ON r.job_id=c.job_id JOIN json_each(r.result_json,'$.output') message JOIN json_each(message.value,'$.content') content WHERE c.scene_id=s.id AND c.purpose='review' AND json_extract(message.value,'$.type')='message' AND json_extract(content.value,'$.type')='output_text' AND json_valid(json_extract(content.value,'$.text')) AND json_extract(json_extract(content.value,'$.text'),'$.pass')=0))))
 BEGIN SELECT RAISE(ABORT,'scene_repair_scope'); END;
CREATE TRIGGER tower_scene_repair_no_update BEFORE UPDATE ON tower_scene_repairs BEGIN SELECT RAISE(ABORT,'scene_repair_immutable'); END;
CREATE TRIGGER tower_scene_repair_no_delete BEFORE DELETE ON tower_scene_repairs BEGIN SELECT RAISE(ABORT,'scene_repair_permanent'); END;
CREATE TRIGGER tower_scene_repair_event_no_update BEFORE UPDATE ON tower_scene_repair_events BEGIN SELECT RAISE(ABORT,'scene_repair_event_immutable'); END;
CREATE TRIGGER tower_scene_repair_event_no_delete BEFORE DELETE ON tower_scene_repair_events BEGIN SELECT RAISE(ABORT,'scene_repair_event_permanent'); END;
CREATE TRIGGER tower_scene_repair_event_scope BEFORE INSERT ON tower_scene_repair_events WHEN EXISTS(SELECT 1 FROM tower_scene_repair_events WHERE repair_id=NEW.repair_id AND event=NEW.event) OR NOT EXISTS(SELECT 1 FROM tower_scene_repairs r JOIN tower_scenes s ON s.id=r.target_id WHERE r.id=NEW.repair_id AND NEW.scene_state=s.state AND ((NEW.event='started' AND s.state='running') OR (NEW.event='settled' AND s.state IN('blocked','unknown','invalid','reviewed','published') AND EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='started')))) BEGIN SELECT RAISE(ABORT,'scene_repair_event_scope'); END;
DROP TRIGGER tower_scene_binding;
CREATE TRIGGER tower_scene_binding BEFORE UPDATE ON tower_scenes WHEN NEW.id!=OLD.id OR NEW.scene_key!=OLD.scene_key OR NEW.period_key IS NOT OLD.period_key OR NEW.batch_id IS NOT OLD.batch_id OR NEW.baseline_sha!=OLD.baseline_sha OR NEW.bible_version!=OLD.bible_version OR NEW.created_at!=OLD.created_at OR NEW.lifetime_budget!=OLD.lifetime_budget OR NEW.daily_budget!=OLD.daily_budget OR NEW.monthly_budget!=OLD.monthly_budget OR (OLD.state IN('published','invalid','unknown') OR (OLD.state='blocked' AND NOT (NEW.state='running' AND NEW.error_code IS NULL AND EXISTS(SELECT 1 FROM tower_scene_repairs r WHERE r.mode='resume' AND r.source_id=OLD.id AND NOT EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='started'))))) OR (OLD.plan_json IS NOT NULL AND NEW.plan_json IS NOT OLD.plan_json) OR (OLD.object_key IS NOT NULL AND (NEW.object_key IS NOT OLD.object_key OR NEW.sha256 IS NOT OLD.sha256 OR NEW.byte_length IS NOT OLD.byte_length OR NEW.width IS NOT OLD.width OR NEW.height IS NOT OLD.height)) BEGIN SELECT RAISE(ABORT,'scene_immutable'); END;
CREATE TRIGGER tower_scene_repair_started AFTER UPDATE OF state ON tower_scenes WHEN NEW.state='running' AND OLD.state IN('pending','blocked') BEGIN INSERT INTO tower_scene_repair_events SELECT id,'started',NEW.state,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM tower_scene_repairs r WHERE r.target_id=NEW.id AND NOT EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='started'); END;
CREATE TRIGGER tower_scene_repair_settled AFTER UPDATE OF state ON tower_scenes WHEN OLD.state='running' AND NEW.state IN('blocked','unknown','invalid','reviewed','published') BEGIN INSERT INTO tower_scene_repair_events SELECT id,'settled',NEW.state,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM tower_scene_repairs r WHERE r.target_id=NEW.id AND EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='started') AND NOT EXISTS(SELECT 1 FROM tower_scene_repair_events e WHERE e.repair_id=r.id AND e.event='settled'); END;
DROP INDEX tower_scene_seed_angle;
CREATE TRIGGER tower_scene_seed_angle BEFORE INSERT ON tower_scenes WHEN NEW.batch_id IS NOT NULL AND EXISTS(SELECT 1 FROM tower_scenes WHERE scene_key=NEW.scene_key AND batch_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM tower_scene_repairs r JOIN tower_scenes s ON s.id=r.source_id WHERE r.mode='replace' AND r.target_id=NEW.id AND r.repair_batch=NEW.batch_id AND r.scene_key=NEW.scene_key AND r.baseline_sha=NEW.baseline_sha AND r.bible_version=NEW.bible_version AND s.lifetime_budget=NEW.lifetime_budget AND s.daily_budget=NEW.daily_budget AND s.monthly_budget=NEW.monthly_budget) BEGIN SELECT RAISE(ABORT,'scene_seed_angle'); END;
DROP TRIGGER tower_scene_seed_batch;
CREATE TRIGGER tower_scene_seed_batch BEFORE INSERT ON tower_scenes WHEN NEW.batch_id IS NOT NULL AND ((SELECT count(*) FROM tower_scenes WHERE batch_id=NEW.batch_id)>=6 OR (NOT EXISTS(SELECT 1 FROM tower_scene_repairs WHERE mode='replace' AND target_id=NEW.id) AND (SELECT count(DISTINCT scene_key) FROM tower_scenes WHERE batch_id IS NOT NULL)>=10) OR (NEW.batch_id LIKE 'repair-%' AND NOT EXISTS(SELECT 1 FROM tower_scene_repairs WHERE mode='replace' AND target_id=NEW.id AND repair_batch=NEW.batch_id))) BEGIN SELECT RAISE(ABORT,'scene_seed_batch_limit'); END;
DROP TRIGGER tower_scene_batch_sequence;
CREATE TRIGGER tower_scene_batch_sequence BEFORE INSERT ON tower_scenes WHEN NEW.batch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tower_scenes WHERE batch_id=NEW.batch_id) AND NOT EXISTS(SELECT 1 FROM tower_scene_repairs WHERE mode='replace' AND target_id=NEW.id AND repair_batch=NEW.batch_id) AND EXISTS(SELECT 1 FROM tower_scene_canonical WHERE batch_id IS NOT NULL AND state!='published') BEGIN SELECT RAISE(ABORT,'scene_seed_batch_pending'); END;

CREATE TRIGGER tower_scene_repair_target_scope BEFORE INSERT ON tower_scenes WHEN EXISTS(SELECT 1 FROM tower_scene_repairs WHERE mode='replace' AND target_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM tower_scene_repairs r JOIN tower_scenes s ON s.id=r.source_id WHERE r.target_id=NEW.id AND r.mode='replace' AND r.scene_key=NEW.scene_key AND r.repair_batch=NEW.batch_id AND NEW.period_key IS NULL AND r.baseline_sha=NEW.baseline_sha AND r.bible_version=NEW.bible_version AND s.lifetime_budget=NEW.lifetime_budget AND s.daily_budget=NEW.daily_budget AND s.monthly_budget=NEW.monthly_budget) BEGIN SELECT RAISE(ABORT,'scene_repair_target_scope'); END;
